function makeResult(overrides = {}) {
  return {
    status: 'success',
    created: 0,
    updated: 0,
    deleted: 0,
    warnings: [],
    errors: [],
    summary: {},
    ...overrides
  };
}

async function syncBlogs({ config, client }) {
  const result = makeResult();
  const sourceBlogs = await client.source.blogs.listAll();
  const destinationBlogs = await client.destination.blogs.listAll();

  const destinationBlogsByHandle = new Map(
    destinationBlogs.map((blog) => [blog.handle, blog])
  );

  for (const sourceBlog of sourceBlogs) {
    const destinationBlog = destinationBlogsByHandle.get(sourceBlog.handle);

    try {
      if (destinationBlog) {
        if (!config.createOnly) {
          await client.destination.blogs.update(destinationBlog.id, sourceBlog);
          result.updated += 1;
        }
      } else if (!config.updateOnly) {
        await client.destination.blogs.create(sourceBlog);
        result.created += 1;
      }
    } catch (error) {
      result.errors.push(`Error processing "${sourceBlog.title}": ${error.message}`);
    }
  }

  if (config.cleanDestination && !config.createOnly && !config.updateOnly) {
    const sourceHandles = new Set(sourceBlogs.map((blog) => blog.handle));

    for (const destinationBlog of destinationBlogs) {
      if (sourceHandles.has(destinationBlog.handle)) {
        continue;
      }

      try {
        await client.destination.blogs.delete(destinationBlog.id);
        result.deleted += 1;
      } catch (error) {
        result.errors.push(
          `Error deleting "${destinationBlog.title}": ${error.message}`
        );
      }
    }
  }

  result.status = result.errors.length > 0 ? 'failed' : 'success';
  result.summary = {
    sourceCount: sourceBlogs.length,
    destinationCount: destinationBlogs.length
  };

  return result;
}

module.exports = {
  syncBlogs
};
